-- TOTO Arena — hand-off schema for Supabase SQL Editor
--
-- Generated from database/migrations/*.php by hand (no PHP/psql available in
-- the environment that wrote this, so it could not be generated by actually
-- running `php artisan migrate` and diffing). Functionally matches the
-- migrations' structure/constraints, but is NOT guaranteed byte-identical to
-- what Laravel's schema builder would emit (e.g. exact timestamp precision).
--
-- Treat the PHP migrations as the source of truth once you have PHP
-- installed and can run `php artisan migrate` for real — re-paste a fresh
-- export then. This file exists only so Supabase has *a* working schema to
-- develop against before that's possible.
--
-- Run top to bottom in Supabase's SQL Editor, once, on a fresh database.

CREATE EXTENSION IF NOT EXISTS vector;

-- ===== Auth & Family =====

CREATE TABLE families (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

-- Laravel's default `users` table, extended with guardian fields.
-- If you've already run Laravel's own starter migration, skip the CREATE
-- and just run the ALTER block below instead.
CREATE TABLE users (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE,
    email_verified_at TIMESTAMP NULL,
    password VARCHAR(255) NOT NULL,
    remember_token VARCHAR(100) NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL,
    family_id BIGINT NULL REFERENCES families(id) ON DELETE SET NULL,
    role VARCHAR(20) NOT NULL DEFAULT 'owner' CHECK (role IN ('owner', 'co_guardian')),
    theme VARCHAR(10) NOT NULL DEFAULT 'system' CHECK (theme IN ('dark', 'light', 'system')),
    two_factor_secret TEXT NULL,
    two_factor_recovery_codes TEXT NULL,
    two_factor_confirmed_at TIMESTAMP NULL
);

CREATE TABLE identities (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    provider VARCHAR(10) NOT NULL CHECK (provider IN ('password', 'google')),
    provider_sub VARCHAR(255) NULL UNIQUE,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL,
    UNIQUE (user_id, provider)
);

CREATE TABLE email_otps (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    code_hash VARCHAR(255) NOT NULL,
    expires_at TIMESTAMP NOT NULL,
    consumed_at TIMESTAMP NULL,
    attempts SMALLINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE consents (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    doc_type VARCHAR(255) NOT NULL,
    doc_version VARCHAR(255) NOT NULL,
    accepted_at TIMESTAMP NOT NULL,
    ip VARCHAR(45) NOT NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE students (
    id BIGSERIAL PRIMARY KEY,
    family_id BIGINT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
    nickname VARCHAR(255) NOT NULL,
    grade VARCHAR(255) NOT NULL,
    track VARCHAR(255) NULL,
    school VARCHAR(255) NULL,
    avatar VARCHAR(255) NULL,
    pin_hash VARCHAR(255) NOT NULL,
    pin_locked_until TIMESTAMP NULL,
    pin_fail_count SMALLINT NOT NULL DEFAULT 0,
    daily_limit_minutes SMALLINT NULL,
    curfew_start TIME NULL,
    curfew_end TIME NULL,
    theme VARCHAR(10) NOT NULL DEFAULT 'dark' CHECK (theme IN ('dark', 'light', 'system')),
    school_google_email VARCHAR(255) NULL UNIQUE,
    level INT NOT NULL DEFAULT 1,
    total_xp BIGINT NOT NULL DEFAULT 0,
    streak_days INT NOT NULL DEFAULT 0,
    last_active_on DATE NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE device_links (
    id BIGSERIAL PRIMARY KEY,
    student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    code VARCHAR(16) NOT NULL UNIQUE,
    expires_at TIMESTAMP NOT NULL,
    used_at TIMESTAMP NULL,
    revoked_at TIMESTAMP NULL,
    device_label VARCHAR(255) NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

-- ===== Curriculum =====

CREATE TABLE subjects (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE grades (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    level_order SMALLINT NOT NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE terms (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE units (
    id BIGSERIAL PRIMARY KEY,
    subject_id BIGINT NOT NULL REFERENCES subjects(id) ON DELETE CASCADE,
    grade_id BIGINT NOT NULL REFERENCES grades(id) ON DELETE CASCADE,
    term_id BIGINT NOT NULL REFERENCES terms(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    "order" SMALLINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE topics (
    id BIGSERIAL PRIMARY KEY,
    unit_id BIGINT NOT NULL REFERENCES units(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    "order" SMALLINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE indicators (
    id BIGSERIAL PRIMARY KEY,
    topic_id BIGINT NOT NULL REFERENCES topics(id) ON DELETE CASCADE,
    code VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

-- ===== Content =====

CREATE TABLE source_files (
    id BIGSERIAL PRIMARY KEY,
    family_id BIGINT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
    uploaded_by BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    unit_id BIGINT NULL REFERENCES units(id) ON DELETE SET NULL,
    topic_id BIGINT NULL REFERENCES topics(id) ON DELETE SET NULL,
    original_filename VARCHAR(255) NOT NULL,
    path VARCHAR(255) NOT NULL,
    mime_type VARCHAR(255) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'uploaded' CHECK (status IN ('uploaded', 'ocr_processing', 'tagging', 'ready', 'failed')),
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE chunks (
    id BIGSERIAL PRIMARY KEY,
    source_file_id BIGINT NOT NULL REFERENCES source_files(id) ON DELETE CASCADE,
    topic_id BIGINT NULL REFERENCES topics(id) ON DELETE SET NULL,
    content TEXT NOT NULL,
    page_number INT NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL,
    embedding VECTOR(1536)
);
CREATE INDEX chunks_embedding_idx ON chunks USING hnsw (embedding vector_cosine_ops);

CREATE TABLE study_materials (
    id BIGSERIAL PRIMARY KEY,
    topic_id BIGINT NOT NULL REFERENCES topics(id) ON DELETE CASCADE,
    type VARCHAR(20) NOT NULL CHECK (type IN ('key_ideas', 'summary', 'cheatsheet', 'mindmap', 'flashcard', 'example')),
    origin VARCHAR(20) NOT NULL CHECK (origin IN ('school', 'external', 'mixed', 'manual')),
    content JSONB NOT NULL,
    version SMALLINT NOT NULL DEFAULT 1,
    published_at TIMESTAMP NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

-- ===== Sourcing =====

CREATE TABLE source_domains (
    id BIGSERIAL PRIMARY KEY,
    domain VARCHAR(255) NOT NULL UNIQUE,
    tier VARCHAR(2) NOT NULL CHECK (tier IN ('T1', 'T2', 'T3')),
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    added_by BIGINT NULL REFERENCES users(id) ON DELETE SET NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE external_sources (
    id BIGSERIAL PRIMARY KEY,
    source_domain_id BIGINT NOT NULL REFERENCES source_domains(id) ON DELETE CASCADE,
    url VARCHAR(2048) NOT NULL,
    title VARCHAR(255) NOT NULL,
    publisher VARCHAR(255) NULL,
    license VARCHAR(255) NULL,
    fetched_at TIMESTAMP NOT NULL,
    content_hash VARCHAR(64) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'changed', 'unreachable')),
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE source_chunks (
    id BIGSERIAL PRIMARY KEY,
    external_source_id BIGINT NOT NULL REFERENCES external_sources(id) ON DELETE CASCADE,
    topic_id BIGINT NULL REFERENCES topics(id) ON DELETE SET NULL,
    indicator_id BIGINT NULL REFERENCES indicators(id) ON DELETE SET NULL,
    content TEXT NOT NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL,
    embedding VECTOR(1536)
);
CREATE INDEX source_chunks_embedding_idx ON source_chunks USING hnsw (embedding vector_cosine_ops);

CREATE TABLE generation_jobs (
    id BIGSERIAL PRIMARY KEY,
    family_id BIGINT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
    requested_by BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    mode VARCHAR(1) NOT NULL CHECK (mode IN ('A', 'B', 'C', 'D', 'E')),
    scope JSONB NOT NULL,
    status VARCHAR(10) NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'done', 'failed')),
    step_index INT NOT NULL DEFAULT 0,
    cost NUMERIC(8, 4) NULL,
    study_material_id BIGINT NULL REFERENCES study_materials(id) ON DELETE SET NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE citations (
    id BIGSERIAL PRIMARY KEY,
    study_material_id BIGINT NOT NULL REFERENCES study_materials(id) ON DELETE CASCADE,
    sentence_ref VARCHAR(255) NOT NULL,
    chunk_id BIGINT NULL REFERENCES chunks(id) ON DELETE CASCADE,
    source_chunk_id BIGINT NULL REFERENCES source_chunks(id) ON DELETE CASCADE,
    quote_excerpt TEXT NOT NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL,
    CONSTRAINT citations_exactly_one_source CHECK (num_nonnulls(chunk_id, source_chunk_id) = 1)
);

CREATE TABLE review_items (
    id BIGSERIAL PRIMARY KEY,
    study_material_id BIGINT NOT NULL REFERENCES study_materials(id) ON DELETE CASCADE,
    flags JSONB NULL,
    decision VARCHAR(10) NOT NULL DEFAULT 'pending' CHECK (decision IN ('pending', 'approved', 'rejected')),
    reviewer_id BIGINT NULL REFERENCES users(id) ON DELETE SET NULL,
    decided_at TIMESTAMP NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

-- ===== Assessment =====

CREATE TABLE items (
    id BIGSERIAL PRIMARY KEY,
    topic_id BIGINT NOT NULL REFERENCES topics(id) ON DELETE CASCADE,
    type VARCHAR(20) NOT NULL CHECK (type IN ('mcq', 'fill_blank', 'matching', 'short_answer', 'essay')),
    difficulty VARCHAR(2) NOT NULL CHECK (difficulty IN ('D1', 'D2', 'D3', 'D4', 'D5')),
    bloom VARCHAR(255) NOT NULL,
    stem TEXT NOT NULL,
    options JSONB NULL,
    correct_key VARCHAR(255) NULL,
    explanation TEXT NULL,
    rubric JSONB NULL,
    source VARCHAR(20) NOT NULL DEFAULT 'ai_generated' CHECK (source IN ('ai_generated', 'manual')),
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE exam_templates (
    id BIGSERIAL PRIMARY KEY,
    family_id BIGINT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
    student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    created_by BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    topic_ids JSONB NOT NULL,
    difficulty VARCHAR(2) NULL CHECK (difficulty IN ('D1', 'D2', 'D3', 'D4', 'D5')),
    item_count SMALLINT NOT NULL,
    duration_minutes SMALLINT NOT NULL,
    mcq_percent SMALLINT NOT NULL DEFAULT 100,
    due_at TIMESTAMP NULL,
    bonus_toton INT NOT NULL DEFAULT 0,
    build_mode VARCHAR(20) NOT NULL DEFAULT 'ai_auto' CHECK (build_mode IN ('ai_auto', 'manual_pick', 'mixed')),
    assigned_at TIMESTAMP NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE exam_template_items (
    id BIGSERIAL PRIMARY KEY,
    exam_template_id BIGINT NOT NULL REFERENCES exam_templates(id) ON DELETE CASCADE,
    item_id BIGINT NOT NULL REFERENCES items(id) ON DELETE CASCADE,
    "order" SMALLINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL,
    UNIQUE (exam_template_id, item_id)
);

CREATE TABLE attempts (
    id BIGSERIAL PRIMARY KEY,
    student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    exam_template_id BIGINT NULL REFERENCES exam_templates(id) ON DELETE SET NULL,
    started_at TIMESTAMP NOT NULL,
    finished_at TIMESTAMP NULL,
    correct_count SMALLINT NOT NULL DEFAULT 0,
    combo SMALLINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE responses (
    id BIGSERIAL PRIMARY KEY,
    attempt_id BIGINT NOT NULL REFERENCES attempts(id) ON DELETE CASCADE,
    item_id BIGINT NOT NULL REFERENCES items(id) ON DELETE CASCADE,
    answer JSONB NOT NULL,
    is_correct BOOLEAN NULL,
    time_spent_seconds INT NOT NULL,
    hints_used SMALLINT NOT NULL DEFAULT 0,
    xp_awarded INT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

-- ===== Learning =====

CREATE TABLE tutor_sessions (
    id BIGSERIAL PRIMARY KEY,
    student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    topic_id BIGINT NULL REFERENCES topics(id) ON DELETE SET NULL,
    hint_stage SMALLINT NOT NULL DEFAULT 0,
    attempt_count SMALLINT NOT NULL DEFAULT 0,
    started_at TIMESTAMP NOT NULL,
    ended_at TIMESTAMP NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE messages (
    id BIGSERIAL PRIMARY KEY,
    tutor_session_id BIGINT NOT NULL REFERENCES tutor_sessions(id) ON DELETE CASCADE,
    role VARCHAR(10) NOT NULL CHECK (role IN ('student', 'toto')),
    type VARCHAR(10) NOT NULL DEFAULT 'text' CHECK (type IN ('text', 'image')),
    content TEXT NOT NULL,
    ocr_text TEXT NULL,
    hint_label VARCHAR(255) NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE mastery_states (
    id BIGSERIAL PRIMARY KEY,
    student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    topic_id BIGINT NOT NULL REFERENCES topics(id) ON DELETE CASCADE,
    mastery_pct SMALLINT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL,
    UNIQUE (student_id, topic_id)
);

-- ===== Game =====

CREATE TABLE xp_events (
    id BIGSERIAL PRIMARY KEY,
    student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    source VARCHAR(255) NOT NULL,
    amount INT NOT NULL,
    meta JSONB NULL,
    created_at TIMESTAMP NOT NULL
);

CREATE TABLE wallets (
    id BIGSERIAL PRIMARY KEY,
    student_id BIGINT NOT NULL UNIQUE REFERENCES students(id) ON DELETE CASCADE,
    toton_balance INT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE coin_txns (
    id BIGSERIAL PRIMARY KEY,
    wallet_id BIGINT NOT NULL REFERENCES wallets(id) ON DELETE CASCADE,
    amount INT NOT NULL,
    reason VARCHAR(255) NOT NULL,
    meta JSONB NULL,
    created_at TIMESTAMP NOT NULL
);

CREATE TABLE crest_awards (
    id BIGSERIAL PRIMARY KEY,
    student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    topic_id BIGINT NOT NULL REFERENCES topics(id) ON DELETE CASCADE,
    tier VARCHAR(10) NOT NULL CHECK (tier IN ('bronze', 'silver', 'gold', 'diamond', 'mythic')),
    awarded_at TIMESTAMP NOT NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL,
    UNIQUE (student_id, topic_id, tier)
);

CREATE TABLE quests (
    id BIGSERIAL PRIMARY KEY,
    student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    assigned_by BIGINT NULL REFERENCES users(id) ON DELETE SET NULL,
    type VARCHAR(10) NOT NULL CHECK (type IN ('daily', 'weekly', 'boss', 'guardian')),
    title VARCHAR(255) NOT NULL,
    target JSONB NOT NULL,
    reward_xp INT NOT NULL DEFAULT 0,
    reward_toton INT NOT NULL DEFAULT 0,
    progress_current INT NOT NULL DEFAULT 0,
    progress_target INT NOT NULL DEFAULT 1,
    completed_at TIMESTAMP NULL,
    claimed_at TIMESTAMP NULL,
    expires_at TIMESTAMP NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE leaderboard_snapshots (
    id BIGSERIAL PRIMARY KEY,
    scope VARCHAR(10) NOT NULL CHECK (scope IN ('weekly', 'apex')),
    student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    rank INT NOT NULL,
    xp BIGINT NOT NULL,
    captured_at TIMESTAMP NOT NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE rewards (
    id BIGSERIAL PRIMARY KEY,
    family_id BIGINT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    price_toton INT NOT NULL,
    limit_rule VARCHAR(255) NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE redemptions (
    id BIGSERIAL PRIMARY KEY,
    reward_id BIGINT NOT NULL REFERENCES rewards(id) ON DELETE CASCADE,
    student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    status VARCHAR(10) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
    decided_by BIGINT NULL REFERENCES users(id) ON DELETE SET NULL,
    decided_at TIMESTAMP NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

-- ===== Activity =====

CREATE TABLE device_sessions (
    id BIGSERIAL PRIMARY KEY,
    student_id BIGINT NULL REFERENCES students(id) ON DELETE CASCADE,
    user_id BIGINT NULL REFERENCES users(id) ON DELETE CASCADE,
    device VARCHAR(255) NULL,
    ip VARCHAR(45) NULL,
    started_at TIMESTAMP NOT NULL,
    ended_at TIMESTAMP NULL,
    created_at TIMESTAMP NULL,
    updated_at TIMESTAMP NULL
);

CREATE TABLE events (
    id BIGSERIAL PRIMARY KEY,
    student_id BIGINT NULL REFERENCES students(id) ON DELETE CASCADE,
    user_id BIGINT NULL REFERENCES users(id) ON DELETE CASCADE,
    type VARCHAR(255) NOT NULL,
    payload JSONB NULL,
    created_at TIMESTAMP NOT NULL
);
CREATE INDEX events_student_id_created_at_idx ON events (student_id, created_at);
